"""Summarize mailbox letters without changing the node."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


NAME = re.compile(r"^\d{8}T\d{4}[-_]")
RESOLVED = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}


def mailboxes(root):
    for box in sorted(root.iterdir(), key=lambda path: path.name):
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if not inbox.is_symlink() and inbox.is_dir():
            yield box.name, inbox


def letters(inbox):
    for where, directory in (("inbox", inbox), ("done", inbox / "done")):
        if directory.is_symlink() or not directory.is_dir():
            continue
        for path in directory.iterdir():
            if (not path.name.startswith(".") and path.suffix == ".md"
                    and not path.is_symlink() and path.is_file()):
                yield path, where


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in ("id", "from", "to", "status", "at")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    return (fields, at), None


def summarize(root, now):
    boxes = {}
    paths = []
    for name, inbox in mailboxes(root):
        boxes[name] = {"inbox": {}, "done": 0}
        for path, where in letters(inbox):
            paths.append((path.relative_to(root).as_posix(), path, name, where))

    bad = []
    valid = []
    seen = set()
    for relative, path, box, where in sorted(paths, key=lambda item: item[0]):
        letter, why = read_letter(path, now)
        if why is None:
            fields, at = letter
            if not NAME.match(path.name):
                why = "bad_name"
            else:
                try:
                    datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
                except ValueError:
                    why = "bad_name"
            if why is None and fields["id"] in seen:
                why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(fields["id"])
        valid.append((fields, at, where))
        if where == "done":
            boxes[box]["done"] += 1
        else:
            counts = boxes[box]["inbox"]
            counts[fields["status"]] = counts.get(fields["status"], 0) + 1

    resolved = {fields["re"] for fields, _, _ in valid
                if fields["status"] in RESOLVED and fields.get("re")}
    opened = [{"id": fields["id"], "from": fields["from"],
               "to": fields["to"], "where": where,
               "age_min": (now - at) // timedelta(minutes=1)}
              for fields, at, where in valid
              if fields["status"] == "REQUEST" and fields["id"] not in resolved]
    opened.sort(key=lambda item: (item["to"], item["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox todo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    try:
        result = summarize(args.folder, now)
    except OSError as error:
        parser.error(str(error))
    print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
